static char* read_all(void) {
    size_t cap = 1 << 16, len = 0;
    char* buf = malloc(cap);
    for (;;) {
        if (len + 1 >= cap) buf = realloc(buf, cap *= 2);
        size_t r = fread(buf + len, 1, cap - len - 1, stdin);
        if (r == 0) break;
        len += r;
    }
    buf[len] = '\0';
    return buf;
}

static char** g_lines;
static int g_count;

static char* line(int i) {
    return i < g_count ? g_lines[i] : "";
}

typedef struct {
    char** t;
    int n, i;
} Tok;

__attribute__((unused)) static Tok tok(const char* s) {
    Tok k = {0};
    char* copy = strdup(s);
    int cap = 16;
    k.t = malloc(cap * sizeof(char*));
    for (char* w = strtok(copy, " \t"); w; w = strtok(NULL, " \t")) {
        if (k.n == cap) k.t = realloc(k.t, (cap *= 2) * sizeof(char*));
        k.t[k.n++] = w;
    }
    return k;
}

__attribute__((unused)) static char* tk_next(Tok* k) {
    return k->i < k->n ? k->t[k->i++] : "0";
}

int main(void) {
    char* input = read_all();
    int cap = 8;
    g_lines = malloc(cap * sizeof(char*));
    for (char* p = input;;) {
        if (g_count == cap) g_lines = realloc(g_lines, (cap *= 2) * sizeof(char*));
        g_lines[g_count++] = p;
        char* nl = strchr(p, '\n');
        size_t n = nl ? (size_t)(nl - p) : strlen(p);
        if (n && p[n - 1] == '\r') p[n - 1] = '\0';
        if (!nl) break;
        *nl = '\0';
        p = nl + 1;
    }
    Tok k0 = tok(line(0));
    int n = (int)strtol(tk_next(&k0), NULL, 10);
    Tok k1 = tok(line(1));
    int flightsSize = atoi(tk_next(&k1));
    int** flights = malloc((flightsSize + 1) * sizeof(int*));
    int* flightsColSize = malloc((flightsSize + 1) * sizeof(int));
    for (int r = 0; r < flightsSize; r++) {
        flightsColSize[r] = atoi(tk_next(&k1));
        flights[r] = malloc((flightsColSize[r] + 1) * sizeof(int));
        for (int j = 0; j < flightsColSize[r]; j++) flights[r][j] = (int)strtol(tk_next(&k1), NULL, 10);
    }
    Tok k2 = tok(line(2));
    int src = (int)strtol(tk_next(&k2), NULL, 10);
    Tok k3 = tok(line(3));
    int dst = (int)strtol(tk_next(&k3), NULL, 10);
    Tok k4 = tok(line(4));
